<?php require_once __DIR__.'/../_init.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();foreach(['wanita','pria'] as $t){$foto=save_upload('foto_'.$t,'mempelai');$sql='INSERT INTO mempelai(tipe,nama_panggilan,nama_lengkap,ayah,ibu,instagram'.($foto?',foto':'').') VALUES(?,?,?,?,?,?'.($foto?',?':'').') ON DUPLICATE KEY UPDATE nama_panggilan=VALUES(nama_panggilan),nama_lengkap=VALUES(nama_lengkap),ayah=VALUES(ayah),ibu=VALUES(ibu),instagram=VALUES(instagram)'.($foto?',foto=VALUES(foto)':'');$p=[$t,trim($_POST['nama_panggilan_'.$t]),trim($_POST['nama_lengkap_'.$t]),trim($_POST['ayah_'.$t]),trim($_POST['ibu_'.$t]),trim($_POST['instagram_'.$t])];if($foto)$p[]=$foto;$pdo->prepare($sql)->execute($p);}flash('success','Data mempelai disimpan.');redirect('edit.php');}$pp=[];foreach($pdo->query('SELECT * FROM mempelai') as $p)$pp[$p['tipe']]=$p;admin_header('Mempelai');?><div class="admin-card"><h1>Mempelai</h1><form method="post" enctype="multipart/form-data" class="form"><?=csrf_field()?><div class="grid2"><?php foreach(['wanita','pria'] as $t):$p=$pp[$t]??[];?><div class="admin-card"><h2><?=ucfirst($t)?></h2><div class="field"><label>Nama Panggilan</label><input name="nama_panggilan_<?=$t?>" value="<?=e($p['nama_panggilan']??'')?>"></div><div class="field"><label>Nama Lengkap</label><input name="nama_lengkap_<?=$t?>" value="<?=e($p['nama_lengkap']??'')?>"></div><div class="field"><label>Ayah</label><input name="ayah_<?=$t?>" value="<?=e($p['ayah']??'')?>"></div><div class="field"><label>Ibu</label><input name="ibu_<?=$t?>" value="<?=e($p['ibu']??'')?>"></div><div class="field"><label>Instagram</label><input name="instagram_<?=$t?>" value="<?=e($p['instagram']??'')?>"></div><div class="field"><label>Foto</label><input type="file" name="foto_<?=$t?>" accept="image/*"></div></div><?php endforeach;?></div><button class="btn">Simpan</button></form></div><?php admin_footer();?>
